contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 newLimit, uint256 wagerValue) public payable {
        require(address(this).balance >= wagerValue);
        c.AdjustBetAmounts(newLimit);
        uint256 lim = c.currentBetLimit();
        bool ok;
        if (wagerValue == lim) {
            c.wager{value: wagerValue}();
            ok = c.hasPlayerWagered(address(this));
        } else {
            bool reverted;
            try c.wager{value: wagerValue}() { reverted = false; } catch { reverted = true; }
            ok = reverted && !c.hasPlayerWagered(address(this));
        }
        assert(lim == newLimit && ok);
    }
    receive() external payable {}
}

