contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);
        c.OpenToThePublic();
        // whale is this contract (set at deployment), which accepts Ether via receive()
        bool reverted;
        uint256 balanceBefore = address(c).balance;
        if (amount > balanceBefore) {
            try c.donate{value: 0}(amount) { reverted = false; } catch { reverted = true; }
        } else {
            // fund c by sending amount first via fallback, then donate
            c.fallback{value: amount}();
            try c.donate{value: 0}(amount) { reverted = false; } catch { reverted = true; }
            // donate sent amount out of c to whale (this contract)
            assert(!reverted);
            assert(address(c).balance == balanceBefore);
        }
        assert(reverted == (amount > balanceBefore));
    }
    receive() external payable {}
}

