        bool reverted;
        try c.wager{value: amount}() { reverted = false; } catch { reverted = true; }

        assert(
            reverted &&
            address(c).balance == balBefore &&
            c.currentBetLimit() == limitBefore &&
            c.currentDifficulty() == diffBefore
        );
    }

    receive() external payable {}
}

